		assertViolatesPrecondition(() -> selectClasspathResource("\t"));

		// with unnecessary "/" prefix
		var selector = selectClasspathResource("/foo/bar/spec.xml");
		assertEquals("foo/bar/spec.xml", selector.getClasspathResourceName());

