		assertEquals(-1, exitCode);
		assertThat(stringWriter.toString()).contains("Unknown option: '--all'").contains("Usage:");
	}

	@ParameterizedTest(name = "{0}")
	@MethodSource("commandsWithEmptyOptionExitCodes")
