		SwallowExceptionHandler.beforeAllCalls = 0;
		SwallowExceptionHandler.beforeEachCalls = 0;
		SwallowExceptionHandler.afterEachCalls = 0;
		SwallowExceptionHandler.afterAllCalls = 0;

