class CollectionUtilsTests {

	@Nested
	class OnlyElement {

		@Test
		void nullCollection() {
			var exception = assertThrows(PreconditionViolationException.class,
				() -> CollectionUtils.getOnlyElement(null));
			assertEquals("collection must not be null", exception.getMessage());
